import {
  defaultChainId,
  defaultVerifiedUrl,
  firebaseConfig,
  methodsToRequests,
} from "../utils/constants";
import { getApp, getApps, initializeApp } from "firebase/app";
import { getMessaging, onBackgroundMessage } from "firebase/messaging/sw";

//on Load/Reload
chrome.runtime.onInstalled.addListener(() => {
  console.log("🎉 Verified Wallet Extension Loaded Successfully! 🚀🔐✨");
  chrome.tabs.update({
    url: defaultVerifiedUrl,
  });
});

const app = getApps().length ? getApp() : initializeApp(firebaseConfig);
const messaging = getMessaging(app);

const saveNotificationToStorage = (notificationData: any) => {
  const storage = chrome.storage.local;

  storage.get("myVault", (res: any) => {
    // Existing user
    if (
      res.myVault &&
      JSON.parse(res.myVault)?.hashedVaultId &&
      JSON.parse(res.myVault)?.address
    ) {
      let myVault = JSON.parse(res.myVault);
      const notifications = myVault?.alert || [];

      // Add new notification to the front
      notifications.unshift(notificationData);

      // Keep only last 10
      if (notifications.length > 10) {
        notifications.length = 10;
      }

      myVault["alerts"] = notifications;

      chrome.storage.local.set({
        myVault: JSON.stringify(myVault),
      });

      console.log(
        "new notification saved. Only last 10 notifications are tracked."
      );
    }
  });
};

// Handle background messages
onBackgroundMessage(messaging, (payload: any) => {
  // console.log("[verified wallet messaging background]", payload);

  const swSelf = self as unknown as ServiceWorkerGlobalScope;

  const notificationTitle =
    payload.notification?.title ?? "🔔 New Notification";
  const notificationOptions = {
    body: payload.notification?.body ?? "You have a new message.",
    icon: chrome.runtime.getURL("assets/icon128.png"),
    badge: chrome.runtime.getURL("assets/icon128.png"),
    requireInteraction: true,
    data: {
      event: payload.data?.event,
      url: payload?.data?.url,
    },
  };

  swSelf.registration.showNotification(notificationTitle, notificationOptions);

  saveNotificationToStorage({
    title: notificationTitle,
    body: notificationOptions?.body,
    timestamp: Date.now(),
  });

  swSelf.addEventListener("notificationclick", (event) => {
    event.notification.close();

    // console.log("Notification clicked with data:", event.notification?.data);

    const urlToOpen = event.notification?.data?.url || defaultVerifiedUrl;

    event.waitUntil(
      swSelf.clients
        .matchAll({ type: "window", includeUncontrolled: true })
        .then((clientList) => {
          for (const client of clientList) {
            if (client.url === urlToOpen && "focus" in client) {
              return client.focus();
            }
          }
          if (swSelf.clients.openWindow) {
            return swSelf.clients.openWindow(urlToOpen);
          }
        })
    );
  });
});

chrome.runtime.onMessage.addListener((req, _, res) => {
  let windowId: number | null = null;
  let isWindowCreated = false;

  const createPopupWindow = async (
    action: string,
    origin: string,
    title: string,
    chainId?: string,
    vaultData?: any,
    txData?: any,
    sigTx?: any
  ) => {
    if (isWindowCreated) {
      chrome.windows.remove(windowId);
    }
    const currentWindow = await new Promise<chrome.windows.Window | null>(
      (resolve) => {
        chrome.windows.getCurrent({ populate: true }, (window) => {
          resolve(window);
        });
      }
    );

    if (!currentWindow) {
      res({ success: false, error: "Unable to get current window" });
      return;
    }

    const { left, top, width, height } = currentWindow;

    const popupWidth = 300;
    const popupHeight = 500;
    const adjustedTop = top + 100;
    const adjustedLeft = left + width - popupWidth - 20;

    chrome.action.setIcon({
      path: {
        16: "../../assets/icon128.png",
        32: "../../assets/icon128.png",
        48: "../../assets/icon128.png",
        128: "../../assets/icon128.png",
      },
    });

    chrome.windows.create(
      {
        url:
          chrome.runtime.getURL("static/popup.html") +
          `?action=${encodeURIComponent(action)}&origin=${encodeURIComponent(
            origin
          )}&title=${encodeURIComponent(title)}&chainId=${encodeURIComponent(
            chainId || defaultChainId
          )}&vaultData=${encodeURIComponent(
            JSON.stringify(vaultData)
          )}&txData=${encodeURIComponent(
            JSON.stringify(txData)
          )}&sigTx=${encodeURIComponent(JSON.stringify(sigTx))}`,
        type: "popup",
        width: popupWidth,
        height: popupHeight,
        top: adjustedTop,
        left: adjustedLeft,
      },
      (nwWindow) => {
        // console.log("Popup window created with ID:", nwWindow.id);
        windowId = nwWindow.id;
        isWindowCreated = true;
      }
    );
  };

  const closePopup = () => {
    if (windowId) {
      chrome.windows.remove(windowId);
    }
  };

  const handleWindowClosed = (winId: number) => {
    if (winId === windowId) {
      // console.log("Popup window closed with ID:", winId);
      res({
        success: false,
        error: "window closed.",
      });
      chrome.windows.onRemoved.removeListener(handleWindowClosed);
    }
  };

  const handleVaultDataReceived = (msg: any, _: any, sndRes: any) => {
    if (msg?.type === "vaultData") {
      res({
        success: true,
        data: [msg.value],
        response: "vaultData received.",
        saveToStorage: true,
      });
      chrome.runtime.onMessage.removeListener(handleVaultDataReceived);
      sndRes({
        success: true,
        data: [msg.value],
        response: "vaultData received.",
      });
    } else if (msg?.type === "txResponse") {
      res({
        success: msg.value?.throwError ? false : true,
        data: msg.value?.hash ? msg.value?.hash : msg.value,
        response: "txResponse received.",
        error: msg.value?.message || msg.value?.reason || msg.value?.code,
      });
      chrome.runtime.onMessage.removeListener(handleVaultDataReceived);
      sndRes({
        success: msg.value?.throwError ? false : true,
        data: msg.value?.hash ? msg.value?.hash : msg.value,
        response: "txResponse received.",
        error: msg.value?.message || msg.value?.reason || msg.value?.code,
      });
    } else if (msg?.type === "getPk") {
      createPopupWindow(
        "getPk",
        req.origin,
        req.title,
        msg.value?.chainId,
        msg.value?.vaultData
      );
    } else if (msg?.type === "signRecovery") {
      createPopupWindow(
        "signRecovery",
        req.origin,
        req.title,
        msg.value?.chainId,
        msg.value?.vaultData,
        msg.value?.txData
      );
    } else if (msg?.type === "completeRecovery") {
      createPopupWindow(
        "completeRecovery",
        req.origin,
        req.title,
        msg.value?.chainId,
        msg.value?.vaultData,
        msg.value?.txData
      );
    } else if (msg?.type === "closePopup") {
      res({
        success: true,
        response: "popup closed.",
      });
      chrome.runtime.onMessage.removeListener(handleVaultDataReceived);
      sndRes({
        success: true,
        response: "popup closed.",
      });
    }
  };

  if (req.type === "VW_REQ") {
    switch (req.params?.method) {
      case methodsToRequests.connectWallet:
        createPopupWindow(
          "connect_wallet",
          req.origin,
          req.title,
          req.params?.params?.chainId
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.eth_requestAccounts:
        createPopupWindow(
          "eth_requestAccounts",
          req.origin,
          req.title,
          req.params?.params?.chainId
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.invitation:
        createPopupWindow(
          "invitation",
          req.origin,
          req.title,
          req.params?.params?.chainId,
          req.params?.params?.vaultData
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.requestPk:
        createPopupWindow(
          "getPk",
          req.origin,
          req.title,
          req.params?.params?.chainId,
          req.params?.params?.vaultData
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.signRecovery:
        createPopupWindow(
          "signRecovery",
          req.origin,
          req.title,
          req.params?.params?.chainId,
          req.params?.params?.vaultData,
          req.params?.params?.txData
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.completeRecovery:
        createPopupWindow(
          "completeRecovery",
          req.origin,
          req.title,
          req.params?.params?.chainId,
          req.params?.params?.vaultData,
          req.params?.params?.txData
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.eth_sendTransaction:
        createPopupWindow(
          "eth_sendTransaction",
          req.origin,
          req.title,
          "",
          "",
          "",
          req.params?.params[0]
        );

        chrome.windows.onRemoved.addListener(handleWindowClosed);
        chrome.runtime.onMessage.addListener(handleVaultDataReceived);

        return true;

      case methodsToRequests.closePopup:
        closePopup();
        return true;

      default:
        res({
          success: false,
          error: `Invalid Request: request method must be one of these: ${Object.values(
            methodsToRequests
          )}`,
        });
        return true;
    }
  }
});
